style.css:
@-moz-document domain("character.ai") {
/* General Page Styling */
    body {
        background: radial-gradient(circle at center, #1a1a1a, #0f0f0f);
        color: #e0e0e0;
        font-family: "Poppins", sans-serif;
        margin: 0;
        padding: 0;
        overflow-x: hidden;
    }

    /* Chat Bubble Styling */
    .message {
        background: linear-gradient(135deg, #252525, #1a1a1a);
        color: #f8f8f8;
        border-radius: 20px;
        padding: 12px 18px;
        margin: 10px;
        max-width: 75%;
        word-wrap: break-word;
        box-shadow: 0 4px 10px rgba(0, 0, 0, 0.7), 0 -2px 5px rgba(255, 255, 255, 0.05);
        position: relative;
        animation: slide-in 0.4s ease-out, fade-in 0.4s ease-out;
        transition: transform 0.3s ease, background-color 0.3s ease;
        cursor: pointer;
    }

    .message:hover {
        transform: scale(1.03);
        background: linear-gradient(135deg, #303030, #202020);
    }

    /* Tails for Chat Bubbles */
    .message.user::after, 
    .message.assistant::after {
        content: "";
        position: absolute;
        width: 0;
        height: 0;
        border-style: solid;
    }

    .message.user::after {
        border-width: 10px 0 10px 10px;
        border-color: transparent transparent transparent #252525;
        right: -10px;
        top: 50%;
        transform: translateY(-50%);
    }

    .message.assistant::after {
        border-width: 10px 10px 10px 0;
        border-color: transparent #252525 transparent transparent;
        left: -10px;
        top: 50%;
        transform: translateY(-50%);
    }

    /* Discover Tab (Cards or Characters) */
    .character-card {
        background: linear-gradient(145deg, #1f1f1f, #141414);
        border-radius: 15px;
        padding: 15px;
        margin: 10px;
        box-shadow: 0 5px 10px rgba(0, 0, 0, 0.5), 0 -2px 5px rgba(255, 255, 255, 0.05);
        transition: transform 0.3s ease, box-shadow 0.3s ease;
    }

    .character-card:hover {
        transform: scale(1.05);
        box-shadow: 0 8px 20px rgba(0, 0, 0, 0.8);
    }

    /* Input Box */
    input[type="text"] {
        background: #181818;
        color: #dcdcdc;
        border: 1px solid #3d3d3d;
        border-radius: 15px;
        padding: 12px 20px;
        font-size: 16px;
        outline: none;
        width: calc(100% - 40px);
        box-shadow: inset 3px 3px 8px rgba(0, 0, 0, 0.7), inset -3px -3px 8px rgba(255, 255, 255, 0.05);
        transition: all 0.3s ease;
    }

    input[type="text"]:focus {
        border-color: #4e4eff;
        box-shadow: 0px 0px 10px rgba(78, 78, 255, 0.7);
    }

    /* Buttons */
    button {
        background: linear-gradient(145deg, #2b2b2b, #1e1e1e);
        color: #f0f0f0;
        border: none;
        padding: 12px 25px;
        border-radius: 15px;
        font-size: 14px;
        cursor: pointer;
        box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.5), -5px -5px 10px rgba(255, 255, 255, 0.05);
        transition: transform 0.2s ease, box-shadow 0.3s ease;
    }

    button:hover {
        transform: scale(1.05);
        box-shadow: 0px 0px 15px rgba(78, 78, 255, 0.7);
    }

    button:active {
        transform: scale(0.95);
        box-shadow: inset 3px 3px 6px rgba(0, 0, 0, 0.7), inset -3px -3px 6px rgba(255, 255, 255, 0.05);
    }

    /* Animations */
    @keyframes fade-in {
        from {
            opacity: 0;
        }
        to {
            opacity: 1;
        }
    }

    @keyframes slide-in {
        from {
            transform: translateY(20px);
        }
        to {
            transform: translateY(0);
        }
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(145deg, #3d3d3d, #2a2a2a);
        border-radius: 10px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #4e4eff;
    }

    ::-webkit-scrollbar-track {
        background: #1a1a1a;
    }

    /* Pointer Styling */
    body {
        cursor: url('https://example.com/custom-pointer.cur'), auto;
    }

    .message:hover {
        cursor: url('https://example.com/hover-pointer.cur'), pointer;
    }
}
